<?php require_once __DIR__.'/../config/bootstrap.php'; require_client();$pdo=db();$pageTitle='Meu Cadastro';$id=current_user()['id'];$st=$pdo->prepare('SELECT * FROM clientes WHERE id=?');$st->execute([$id]);$row=$st->fetch();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$nome=trim($_POST['nome']??'');$tel=trim($_POST['telefone']??'');$email=trim($_POST['email']??'');$end=trim($_POST['endereco']??'');$nova=$_POST['senha']??'';if(!$nome)$error='Nome é obrigatório.';elseif($nova!==''&&strlen($nova)<6)$error='A nova senha deve possuir pelo menos 6 caracteres.';else{if($nova!=='')$pdo->prepare('UPDATE clientes SET nome=?,telefone=?,email=?,endereco=?,senha_hash=?,atualizado_em=? WHERE id=?')->execute([$nome,$tel,$email,$end,password_hash($nova,PASSWORD_DEFAULT),now(),$id]);else$pdo->prepare('UPDATE clientes SET nome=?,telefone=?,email=?,endereco=?,atualizado_em=? WHERE id=?')->execute([$nome,$tel,$email,$end,now(),$id]);$_SESSION['user']['name']=$nome;log_action('alteração de cliente','clientes',$id);flash('success','Cadastro atualizado com sucesso.');redirect('perfil.php');}}include __DIR__.'/../includes/header.php'; ?><div class="page-head"><h1>Meu Cadastro</h1></div><div class="card"><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field col-6"><label>Nome</label><input name="nome" value="<?=e($row['nome'])?>" required></div><div class="field col-3"><label>Telefone</label><input name="telefone" value="<?=e($row['telefone'])?>"></div><div class="field col-3"><label>Login</label><input value="<?=e($row['login'])?>" disabled></div><div class="field col-6"><label>E-mail</label><input type="email" name="email" value="<?=e($row['email'])?>"></div><div class="field col-6"><label>CPF/CNPJ</label><input value="<?=e($row['cpf_cnpj'])?>" disabled></div><div class="field col-12"><label>Endereço</label><input name="endereco" value="<?=e($row['endereco'])?>"></div><div class="field col-6"><label>Nova senha</label><input type="password" name="senha"></div></div><div class="form-actions"><button class="btn primary">Salvar alterações</button></div></form></div><?php include __DIR__.'/../includes/footer.php'; ?>
